create table public.exams (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete restrict,course_id uuid not null references public.courses(id) on delete restrict,title text not null check(char_length(trim(title)) between 2 and 200),description text,starts_at timestamptz,ends_at timestamptz,status text not null default 'DRAFT' check(status in('DRAFT','PUBLISHED','CLOSED')),created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),check(ends_at is null or starts_at is null or ends_at>starts_at));create index exams_tenant_idx on public.exams(tenant_id,starts_at);alter table public.exams enable row level security;revoke all on public.exams from anon,authenticated;create policy exams_select_tenant on public.exams for select to authenticated using(tenant_id=public.current_tenant_id());insert into public.permissions(code,name,description) values('exams.read','Read exams','View exams'),('exams.create','Create exams','Create exams'),('exams.update','Update exams','Maintain exams'),('exams.delete','Delete exams','Delete exams') on conflict(code) do nothing;insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('OWNER','PRINCIPAL','STAFF','TEACHER') and p.code like 'exams.%' on conflict do nothing;
